def _tinh_cay(nut: ast.AST, an: tuple[str, float] | None=None) -> float:
    if isinstance(nut, ast.Num):
        return nut.n
    elif isinstance(nut, ast.BinOp):
        return _PHEP[type(nut.op)](_tinh_cay(nut.left, an), _tinh_cay(nut.right, an))
    elif isinstance(nut, ast.UnaryOp):
        return _PHEP[type(nut.op)](_tinh_cay(nut.operand, an))
    elif isinstance(nut, ast.Name):
        if an and nut.id == an[0]:
            return an[1]
        else:
            raise ValueError(f"Tên không hợp lệ: {nut.id}")
    else:
        raise ValueError(f"Kiểu node không hợp lệ: {type(nut)}")

def _doc_ngay(text: str, hom_nay: date) -> date | None:
    khop = _NGAY_THANG.search(text)
    if khop:
        ngay, thang, nam = khop.groups()
        nam = nam or hom_nay.year
        thang = thang or hom_nay.month
        ngay = ngay or hom_nay.day
        return date(int(nam), int(thang), int(ngay))
    return None
