def giai_phuong_trinh(text: str) -> str | None:
    text = _bo_dau(text or '')
    if not re.fullmatch('\\s*[+-]?\\d+\\s*x\\s*=\\s*[+-]?\\d+\\s*', text):
        return None
    a, b = map(int, re.findall('\\d+', text))
    if a == 0:
        return None
    return f'x = {b / a:.2f}'

